  {id:'strength',jp:'力',en:'Physical Power'},
  {id:'speed',jp:'速',en:'Agility & Reflexes'},
  {id:'endurance',jp:'耐',en:'Endurance'},
  {id:'perception',jp:'感',en:'Perception'},
  {id:'focus',jp:'集',en:'Concentration'},
  {id:'technique',jp:'技',en:'Combat Skill'},
  {id:'spirit',jp:'霊',en:'Spiritual Pressure'},
  {id:'willpower',jp:'意',en:'Willpower'}
];
var SCENARIOS={
  peaceful:{ico:'🌸',title:'Peaceful Days',jp:'平和な時代'},
  first_mission:{ico:'⚔️',title:'First Mission',jp:'初任務'},
