function statLevel(v){
  if(v<100)return{label:'凡',en:'Ordinary',color:'#786858'};
  if(v<300)return{label:'練',en:'Trained',color:'#9A8060'};
  if(v<500)return{label:'鍛',en:'Seasoned',color:'#B09040'};
  if(v<700)return{label:'精',en:'Elite',color:'#C9922A'};
  if(v<850)return{label:'柱',en:'Pillar',color:'#9B6FAE'};
  if(v<980)return{label:'鬼',en:'Demon-Tier',color:'#C8384A'};
  if(v<1000)return{label:'極',en:'Extreme',color:'#FF4444'};
  return{label:'無',en:'Absolute',color:'#FFD700'};
}
function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
function g(id){return document.getElementById(id)}
function setText(id,val){var e=g(id);if(e)e.textContent=val||'—'}
function setHtml(id,val){var e=g(id);if(e)e.innerHTML=val||''}
function hexRgb(h){
  if(!h||h.length<7)return'139,111,174';
  return parseInt(h.slice(1,3),16)+','+parseInt(h.slice(3,5),16)+','+parseInt(h.slice(5,7),16);
}

