      '</div>'+
      (d.howTurned?'<div class="kc-text-block" style="margin-bottom:0">'+esc(d.howTurned)+'</div>':'')+
    '</div>';
  }else{
    facDetail.innerHTML='<div class="kc-info-item" style="border-radius:8px;background:var(--pan2);border:1px solid var(--bd2);padding:8px 10px">'+
      '<div class="kc-info-lbl">Occupation 職業</div><div class="kc-info-val">'+esc(d.occupation||'—')+'</div></div>';
  }
